// Replays recorded Rule 110 runs (window.JEV_LIVE_RUN, window.JEV_RECORDED_RUN) and the ad's numbers
// (window.JEV_AD_FACTS). No network calls; nothing here talks to an AI.
(function () {
  "use strict";
  const $ = (id) => document.getElementById(id);
  const fmt = (n) => Number(n).toLocaleString("en-US");

  // ---- Numbers shared with the ad (generated by python -m jev_turing.media_ad) ----
  const F = window.JEV_AD_FACTS || {};
  const T = F.text || {}; // pre-formatted by Python so the page matches the ad digit for digit
  const derived = {
    calls: T.calls, wrong: F.wrong, bound_one_in: T.bound_one_in, median_s: T.median_s,
    min_conf_pct: T.min_conf_pct, fake_cells_off: F.fake_cells_off, live64_cells_off: F.live64_cells_off,
    python_ms_r: T.python_ms, minutes_r: T.minutes, cost_r: T.cost,
  };
  document.querySelectorAll("[data-f]").forEach((el) => {
    const v = derived[el.dataset.f];
    el.textContent = v == null ? "?" : v;
  });
  if (F.fine_print) $("fine-print").textContent = F.fine_print;

  // ---- Recorded runs ----
  const runs = [
    { key: "live", label: "Live Jev (200 ticks)", run: window.JEV_LIVE_RUN },
    { key: "fake", label: "Simulated gate, 0.1% wrong (not an AI)", run: window.JEV_RECORDED_RUN },
  ].filter((r) => r.run);
  if (!runs.length) { $("disclaimer").textContent = "No recorded run found (site/data/)."; return; }
  const want = new URLSearchParams(location.search).get("run");
  const chosen = runs.find((r) => r.key === want) || runs[0];
  const run = chosen.run;
  const isLive = !run.backend.startsWith("fake-jev");
  const liveRun = window.JEV_LIVE_RUN;

  runs.forEach((r) => {
    const b = document.createElement("button");
    b.type = "button"; b.setAttribute("role", "radio"); b.textContent = r.label;
    b.setAttribute("aria-checked", String(r === chosen));
    b.addEventListener("click", () => { location.search = "?run=" + r.key; });
    $("pick").appendChild(b);
  });
  if (runs.length < 2) $("pick").hidden = true;

  $("disclaimer").textContent = isLive
    ? `Live: ${fmt(run.counters.jev_calls)} real calls to the model on 2026-10-09, ${run.counters.local_errors} wrong. ` +
      "Replayed here; this page makes no calls."
    : "Simulation, not an AI: an offline stand-in that gives the wrong answer 0.1% of the time. " +
      "Shown so you can see what mistakes look like. No AI calls were made.";
  $("disclaimer").classList.toggle("live", isLive);
  $("c-calls-k").textContent = isLive ? "AI calls" : "simulated calls";
  if (want === "fake" || want === "live") $("fn1").scrollIntoView();

  // The exact question (always from the live run, since that's what was sent).
  const spec = (liveRun || run).spec;
  if (spec) {
    $("q-text").textContent = spec.question.text;
    const cat = Object.fromEntries(spec.categories.map((c) => [c.id, c.definition]));
    $("q-true").textContent = cat.true || "";
    $("q-false").textContent = cat.false || "";
  }

  const cost = run.meta && run.meta.cost_usd;
  $("meta").textContent = `${run.backend} · start pattern ${run.init.pattern} · background ${run.background.name}` +
    (cost != null ? ` · cost $${cost.toFixed(4)}` : "");
  $("download").download = chosen.key + "-run.json";
  $("download").href = URL.createObjectURL(new Blob([JSON.stringify(run)], { type: "application/json" }));

  const rows = run.rows, refs = run.reference_rows || [];
  const cols = run.call_log.columns, calls = run.call_log.rows;
  const ci = Object.fromEntries(cols.map((c, i) => [c, i]));
  const lo = Math.min(...rows.concat(refs).map((r) => r.lo));
  const hi = Math.max(...rows.concat(refs).map((r) => r.lo + r.cells.length));
  const W = hi - lo, H = rows.length, S = 6;
  const period = run.background.period || (rows[0].bg || "").length || 1;

  // Index calls by step, and by (t, kind, x) for receipts.
  const byStep = rows.map(() => []);
  const byKey = new Map();
  const errCells = new Set();
  calls.forEach((c) => {
    byStep[c[ci.t]].push(c);
    byKey.set(`${c[ci.t]},${c[ci.kind]},${c[ci.x]}`, c);
    if (c[ci.kind] === "tape" && c[ci.error]) errCells.add(`${c[ci.t] + 1},${c[ci.x]}`);
  });
  const mod = (a, n) => ((a % n) + n) % n;
  const cellAt = (row, x) => {
    const i = x - row.lo;
    if (i >= 0 && i < row.cells.length) return [row.cells[i] === "1", true];
    return [row.bg[mod(x, row.bg.length)] === "1", false];
  };

  const canvas = $("spacetime");
  canvas.width = W * S; canvas.height = H * S;
  const ctx = canvas.getContext("2d");
  let t = 0, playing = true, callsSoFar = 0, errorsSoFar = 0, timer = null, selected = null;

  function colorAt(y, x) {
    const row = rows[y], ref = refs[y];
    const [v, inside] = cellAt(row, x);
    let color = inside ? (v ? "#e6e6e1" : "#111114") : (v ? "#5a5a5f" : "#1e1e22");
    if (ref && cellAt(ref, x)[0] !== v) color = v ? "#ff5050" : "#6e1418";
    if (errCells.has(`${y},${x}`)) color = "#ffbe28";
    return color;
  }
  function drawRow(y) {
    for (let x = lo; x < hi; x++) { ctx.fillStyle = colorAt(y, x); ctx.fillRect((x - lo) * S, y * S, S, S); }
  }
  function drawSelection() {
    if (!selected || selected.y >= t) return;
    ctx.strokeStyle = "#3fbf7f"; ctx.lineWidth = 2;
    ctx.strokeRect((selected.x - lo) * S - 1, selected.y * S - 1, S + 2, S + 2);
  }
  function clearSelection() {
    if (!selected || selected.y >= t) return;
    const { x, y } = selected;
    for (let yy = y - 1; yy <= y + 1; yy++) {
      if (yy < 0 || yy >= t) continue;
      for (let xx = x - 1; xx <= x + 1; xx++) {
        if (xx < lo || xx >= hi) continue;
        ctx.fillStyle = colorAt(yy, xx); ctx.fillRect((xx - lo) * S, yy * S, S, S);
      }
    }
  }

  function logStep(stepCalls) {
    const log = $("log");
    const frag = document.createDocumentFragment();
    stepCalls.slice(-40).forEach((c) => {
      const li = document.createElement("li");
      const p = c[ci.p_true] != null ? ` (${Math.round(c[ci.p_true] * 100)}%)` : "";
      li.textContent = `tick ${c[ci.t]} ${c[ci.kind] === "bg" ? "background" : "cell"} ${c[ci.x]}: ` +
        `${c[ci.L]}${c[ci.C]}${c[ci.R]} → ${c[ci.out]}${p}` + (c[ci.error] ? `  ✗ should be ${c[ci.expected]}` : "");
      if (c[ci.error]) li.className = "bad";
      frag.prepend(li);
    });
    log.prepend(frag);
    while (log.children.length > 200) log.removeChild(log.lastChild);
  }

  function frame() {
    if (t >= H) { playing = false; $("play").textContent = "Play"; return; }
    drawRow(t);
    if (t > 0) {
      const sc = byStep[t - 1];
      callsSoFar += sc.reduce((a, c) => a + (c[ci.calls] || 1), 0);
      errorsSoFar += sc.filter((c) => c[ci.error]).length;
      logStep(sc);
    }
    const ps = run.per_step[t - 1];
    $("c-step").textContent = t;
    $("c-calls").textContent = fmt(callsSoFar);
    $("c-errors").textContent = errorsSoFar;
    $("c-div").textContent = ps ? ps.divergent_cells : 0;
    t++;
    drawSelection();
  }
  function loop() {
    clearTimeout(timer);
    if (!playing) return;
    frame();
    timer = setTimeout(loop, 1000 / Number($("speed").value));
  }
  function restart() {
    t = 0; callsSoFar = 0; errorsSoFar = 0;
    ctx.fillStyle = "#000"; ctx.fillRect(0, 0, canvas.width, canvas.height);
    $("log").replaceChildren();
    playing = true; $("play").textContent = "Pause"; loop();
  }
  function skipToEnd() {
    clearTimeout(timer); playing = false;
    while (t < H) frame();
    $("play").textContent = "Replay";
  }
  $("play").addEventListener("click", () => {
    if (t >= H) return restart();
    playing = !playing; $("play").textContent = playing ? "Pause" : "Play"; loop();
  });
  $("restart").addEventListener("click", restart);
  $("skip").addEventListener("click", skipToEnd);

  // ---- Receipts: click a cell, see the call that decided it ----
  const onOff = (b) => (b ? "on" : "off");
  function receipt(x, y) {
    if (y < 1 || y >= H) {
      $("r-empty").hidden = false; $("r-body").hidden = true;
      $("r-msg").textContent = y === 0
        ? "Top row: the starting pattern. It was typed in, not decided by a call. Click any row below it"
        : "Click a cell in the picture";
      return;
    }
    const row = rows[y];
    const inside = x >= row.lo && x < row.lo + row.cells.length;
    const c = inside ? byKey.get(`${y - 1},tape,${x}`) : byKey.get(`${y - 1},bg,${mod(x, period)}`);
    if (!c) { $("r-empty").hidden = false; $("r-body").hidden = true; $("r-msg").textContent = "No call recorded for that cell"; return; }
    clearSelection(); selected = { x, y }; drawSelection();
    $("r-empty").hidden = true; $("r-body").hidden = false;
    $("r-k").textContent = isLive ? "Receipt: one live call" : "Receipt: one simulated call (not an AI)";
    $("r-where").textContent = inside
      ? `Tick ${y}, cell ${x}. Decided by call ${calls.indexOf(c) + 1} of ${fmt(calls.length)}.`
      : `Tick ${y}, background. The repeating background is one ${period}-cell pattern; this pixel copies pattern cell ` +
        `${mod(x, period)}, which was decided by call ${calls.indexOf(c) + 1} of ${fmt(calls.length)}.`;
    [["r-l", ci.L], ["r-c", ci.C], ["r-r", ci.R], ["r-a", ci.out]].forEach(([id, i]) => {
      $(id).className = "cell " + onOff(c[i]);
    });
    const state = `L=${!!c[ci.L]}; C=${!!c[ci.C]}; R=${!!c[ci.R]}`;
    $("r-state").textContent = state;
    const p = c[ci.p_true];
    $("r-p").textContent = p != null
      ? `${Math.round(p * 100)}% sure it's on → ${onOff(c[ci.out])}`
      : `${onOff(c[ci.out])} (simulated; no probability)`;
    $("r-v").textContent = `${onOff(c[ci.expected])}: ` + (c[ci.error] ? "WRONG" : "matches");
    $("r-v").className = c[ci.error] ? "err-text" : "ok-text";
    const lat = c[ci.latency_ms];
    $("r-lat-row").hidden = lat == null;
    if (lat != null) $("r-lat").textContent = `${Math.round(lat)} ms`;
    if (isLive && spec) {
      const cat = Object.fromEntries(spec.categories.map((k) => [k.id, k.definition]));
      $("r-payload").textContent = "POST https://ai-gateway.vercel.sh/v1/evaluate\n" + JSON.stringify({
        model: "typesafe-ai/jev", state,
        questions: { answer: { type: "boolean", instructions: spec.question.text,
          criteria: { true: cat.true, false: cat.false } } },
      }, null, 2);
    } else {
      $("r-payload").textContent = "Simulated run: no request was sent.";
    }
  }
  function cellFromEvent(ev) {
    const r = canvas.getBoundingClientRect();
    const px = (ev.clientX - r.left) * (canvas.width / r.width);
    const py = (ev.clientY - r.top) * (canvas.height / r.height);
    return { x: lo + Math.floor(px / S), y: Math.floor(py / S) };
  }
  canvas.addEventListener("click", (ev) => {
    const { x, y } = cellFromEvent(ev);
    if (y >= t) skipToEnd();
    receipt(x, y);
  });
  $("r-random").addEventListener("click", () => {
    skipToEnd();
    const tape = calls.filter((k) => k[ci.kind] === "tape");
    const c = tape[Math.floor(Math.random() * tape.length)];
    receipt(c[ci.x], c[ci.t] + 1);
  });
  window.__jevReceipt = receipt; // for tests

  // ---- Footnotes 2 and 3: histograms from the live call log ----
  function histogram(id, values, { bins, min, max, color, label, mark }) {
    const cv = $(id); if (!cv || !values.length) return;
    const g = cv.getContext("2d"), Wc = cv.width, Hc = cv.height, pad = 34;
    const counts = new Array(bins).fill(0);
    values.forEach((v) => { counts[Math.min(bins - 1, Math.max(0, Math.floor((v - min) / (max - min) * bins)))]++; });
    const top = Math.max(...counts);
    g.fillStyle = "#0f1115"; g.fillRect(0, 0, Wc, Hc);
    const bw = (Wc - 2 * pad) / bins;
    counts.forEach((n, i) => {
      const h = n ? Math.max(2, (Hc - 2 * pad) * Math.sqrt(n / top)) : 0; // sqrt scale so small bins stay visible
      g.fillStyle = color; g.fillRect(pad + i * bw + 1, Hc - pad - h, bw - 2, h);
    });
    g.fillStyle = "#8a8f98"; g.font = "13px system-ui, sans-serif"; g.textAlign = "center";
    label.forEach(([v, s]) => g.fillText(s, pad + (v - min) / (max - min) * (Wc - 2 * pad), Hc - 12));
    if (mark) {
      const xm = pad + (mark.v - min) / (max - min) * (Wc - 2 * pad);
      g.strokeStyle = "#ffbe28"; g.setLineDash([5, 5]); g.beginPath(); g.moveTo(xm, 14); g.lineTo(xm, Hc - pad); g.stroke();
      g.setLineDash([]); g.fillStyle = "#ffbe28"; g.fillText(mark.s, xm, 14);
    }
  }
  if (liveRun) {
    const lc = liveRun.call_log.columns, li = Object.fromEntries(lc.map((c, i) => [c, i]));
    const lr = liveRun.call_log.rows;
    histogram("hist", lr.map((c) => c[li.p_true]).filter((v) => v != null), {
      bins: 50, min: 0, max: 1, color: "#e6e6e1",
      label: [[0.02, "sure it's off"], [0.25, "25%"], [0.75, "75%"], [0.98, "sure it's on"]],
      mark: { v: 0.5, s: "50%: where a coin flip would be" },
    });
    const lats = lr.map((c) => c[li.latency_ms]).filter((v) => v != null).sort((a, b) => a - b);
    const p99 = lats[Math.floor(lats.length * 0.99)];
    histogram("lat", lats.filter((v) => v <= 1000), {
      bins: 50, min: 0, max: 1000, color: "#ffd65c",
      label: [[0, "0"], [250, "250 ms"], [500, "500 ms"], [750, "750 ms"], [1000, "1 s"]],
      mark: { v: F.median_ms || lats[lats.length >> 1], s: `typical: ${T.median_ms || Math.round(lats[lats.length >> 1])} ms` },
    });
    const over = lats.filter((v) => v > 1000).length;
    $("lat-cap").append(` 99% of calls took under ${Math.round(p99)} ms` + (over ? `; ${fmt(over)} took over 1 s (not shown).` : "."));
  }

  restart();
})();
